import json
d=json.load(open('products/services/software-renewals/raw/fts-awards-page1.json'))
def walk(o,p=''):
  if isinstance(o,dict):
    for k,v in o.items(): yield from walk(v,p+'.'+k)
  elif isinstance(o,list):
    for i,v in enumerate(o): yield from walk(v,p+'[%d]'%i)
  else: yield p,o
for r in d['releases']:
  if r['id'] in ('105970-2026','105806-2026','105743-2026'):
    print('=====',r['id'])
    for p,v in walk(r):
      lp=p.lower()
      if any(s in lp for s in ('period','date','value','description','title','duration','renew','option','status','classification.id','suppliers','scheme','procurementmethod')) and 'parties' not in lp and 'address' not in lp and 'contactpoint' not in lp:
        print(p,'=',str(v)[:400])
